#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Plateful's one-time AWS and GitHub setup: the steps only the human can do (infra/AGENTS.md).
# Run it from the repo on the host: scripts/aws-setup.sh. It needs Docker, git, GNU make and an
# authenticated gh; every AWS and Terraform command runs in the toolchain container (`make aws`).
# The temporary admin credentials live only in this process's environment, which passes them to
# the container per command. Nothing secret is printed or written to the repo. The only file it
# writes in the repo is .aws-setup.env (gitignored, no secrets): the account ID and profile name.
# Every stage checks what is already done, so it is safe to re-run.

REGION=ca-west-1
STACKS=(staging prod)
DEV_USER=plateful-staging-dev
MAKE_BIN=$(command -v gmake || command -v make || true)

# in_aws CMD: run CMD with bash in the toolchain container, with this wizard's AWS credentials.
# Stdin passes through, so a secret can be piped in without appearing on a command line.
in_aws() { CMD=$1 "$MAKE_BIN" -s --no-print-directory aws; }

# set_env_var ENVIRONMENT NAME VALUE sets a GitHub Actions variable on one environment.
set_env_var() {
  if gh variable set "$2" --env "$1" --body "$3" -R "$REPO_SLUG" >/dev/null; then
    printf '  %s✓ set%s %s variable %s\n' "$GREEN" "$RESET" "$1" "$2"
  else
    SKIPPED+=("GitHub variable $2 on environment $1")
    warn "couldn't set $2 on $1"
  fi
}

# load_outputs STACK reads the stack's Terraform outputs into DOMAIN_<stack>, DIST_ARN_<stack> and
# ACL_ARN_<stack>. Fails when the stack has never been applied.
load_outputs() {
  local s=$1 domain dist acl cached=DOMAIN_$1
  [[ -n ${!cached:-} ]] && return 0
  { read -r domain && read -r dist && read -r acl; } < <(in_aws "
    export TF_PLUGIN_CACHE_DIR=\$XDG_CACHE_HOME/terraform-plugins && mkdir -p \$TF_PLUGIN_CACHE_DIR
    terraform -chdir=infra/stacks/$s init -input=false -reconfigure -backend-config=bucket=$STATE_BUCKET >/dev/null
    for o in distribution_domain distribution_arn web_acl_arn; do terraform -chdir=infra/stacks/$s output -raw \$o; echo; done
  " 2>/dev/null) || return 1
  [[ $domain == *.cloudfront.net ]] || return 1
  printf -v "DOMAIN_$s" '%s' "$domain"
  printf -v "DIST_ARN_$s" '%s' "$dist"
  printf -v "ACL_ARN_$s" '%s' "$acl"
}

# param_version NAME prints the SSM parameter's version. Terraform writes version 1, a placeholder.
param_version() { in_aws "aws ssm get-parameter --name $1 --query Parameter.Version --output text"; }

# should_set NAME succeeds when NAME still holds the placeholder, or the human wants to replace it.
should_set() {
  local v
  v=$(param_version "$1" 2>/dev/null) || { warn "can't read $1: has its stack been applied?"; return 1; }
  [[ $v == 1 ]] && return 0
  note "$1 is already set (version $v)."
  confirm "Replace it?"
}

# put_param NAME [PIPELINE]: store stdin, or PIPELINE's output made in the container, as NAME's
# SecureString value. The value goes through a pipe only.
put_param() {
  in_aws "${2:+$2 | }aws ssm put-parameter --name $1 --type SecureString --overwrite --value file:///dev/stdin >/dev/null" &&
    printf '  %s✓ set%s %s\n' "$GREEN" "$RESET" "$1"
}

# stack_secrets STACK: the three SecureStrings the sign-in ADR names, under /plateful/<stack>/.
stack_secrets() {
  local s=$1 p=/plateful/$1 emails token
  say "The API reads three secrets from SSM Parameter Store. Terraform made them with a placeholder"
  say "and never stores or reverts their values (value_wo)."
  printf '\n'
  if should_set "$p/editor-allowlist"; then
    say "The editors' Google email addresses, comma-separated (the household's two)."
    ask emails "Editor emails:"
    printf '%s' "$emails" | put_param "$p/editor-allowlist"
  fi
  if should_set "$p/session-hmac-key"; then
    say "The session cookie signing key: 32 random bytes, made in the container and never shown."
    put_param "$p/session-hmac-key" "head -c 32 /dev/urandom | base64 -w0" </dev/null
    note "Replacing it later signs every editor out."
  fi
  if should_set "$p/service-token-hash"; then
    step "In your password manager, generate a random password of 40+ characters and save it as"
    step "\"Plateful $s service token\". The CLIs send it; SSM keeps only its SHA-256."
    ask_secret token "Paste the token (hidden):"
    [[ -n $token ]] || { warn "empty token: skipped"; return 0; }
    printf '%s' "$token" | put_param "$p/service-token-hash" "sha256sum | cut -d' ' -f1 | tr -d '\n'"
    unset token
    [[ $s == staging ]] && note "It is also the e2e editor: add it as a staging environment secret when a job needs it."
  fi
  note "A running Lambda reads them at cold start, so a change applies on the next deploy."
}

run_wizard() {

TOTAL_STAGES=13
ENV_FILE=.aws-setup.env

cd "$(git rev-parse --show-toplevel)"
banner "Plateful: AWS account and release setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "You need: Docker running, GNU make 4+, gh signed in to GitHub, and admin access to the AWS"
say "account Plateful lives in. Nothing else is installed on this machine."
printf '\n'
command -v docker >/dev/null || { warn "docker not found"; exit 1; }
[[ -n $MAKE_BIN ]] && "$MAKE_BIN" --version | grep -q 'GNU Make [45]' ||
  { warn "GNU make 4 or later not found (macOS: brew install make)"; exit 1; }
command -v gh >/dev/null && gh auth status >/dev/null 2>&1 ||
  { warn "gh isn't signed in: run gh auth login, then re-run this wizard"; exit 1; }
REPO_SLUG=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
say "Repository: ${BOLD}$REPO_SLUG${RESET}  ·  region: ${BOLD}$REGION${RESET}"
note "The first run builds the toolchain image, which takes a few minutes."
pause "Press Enter to check the toolchain image"
in_aws 'aws --version && terraform version | head -n1'

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "AWS: temporary admin credentials"
say "Use short-lived admin credentials. This wizard keeps them in memory and passes them to the"
say "container for each command; they're never written to disk."
printf '\n'
say "${BOLD}Either${RESET} IAM Identity Center: open your AWS access portal, pick the account and"
step "your admin role → Access keys, and copy AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_SESSION_TOKEN."
say "${BOLD}Or${RESET}, without Identity Center: IAM → Users → your admin user → Security credentials"
step "→ Create access key → Command Line Interface. Stage 13 has you delete it again."
open_url "https://console.aws.amazon.com/iam/home?region=$REGION#/security_credentials"
printf '\n'
ask_secret AWS_ACCESS_KEY_ID "AWS_ACCESS_KEY_ID (hidden):"
ask_secret AWS_SECRET_ACCESS_KEY "AWS_SECRET_ACCESS_KEY (hidden):"
ask_secret AWS_SESSION_TOKEN "AWS_SESSION_TOKEN (hidden; Enter if you made an access key):"
export AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY AWS_REGION=$REGION AWS_DEFAULT_REGION=$REGION
if [[ -n $AWS_SESSION_TOKEN ]]; then export AWS_SESSION_TOKEN; USED_ACCESS_KEY=no
else unset AWS_SESSION_TOKEN; USED_ACCESS_KEY=yes; fi
read -r ACCOUNT CALLER < <(in_aws 'aws sts get-caller-identity --query "[Account,Arn]" --output text') ||
  { warn "AWS rejected those credentials. Re-run the wizard with fresh ones."; exit 1; }
say "Signed in to account ${BOLD}$ACCOUNT${RESET} as $CALLER"
confirm "Is this the account Plateful should live in?" || exit 1
write_env AWS_ACCOUNT_ID "$ACCOUNT"
STATE_BUCKET=plateful-tfstate-$ACCOUNT
export TF_STATE_BUCKET=$STATE_BUCKET

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Bootstrap, step 1: apply with local state"
say "infra/bootstrap makes the Terraform state bucket ($STATE_BUCKET), GitHub's OIDC provider, and"
say "each stack's deploy role and permissions boundary. The bucket must exist before state can"
say "live in it, so the first apply keeps its state in a local file."
printf '\n'
if in_aws "aws s3api head-bucket --bucket $STATE_BUCKET" >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} $STATE_BUCKET already exists, so the account is bootstrapped."
  if confirm "Apply infra/bootstrap again from its S3 state, to pick up changes?"; then
    in_aws "terraform -chdir=infra/bootstrap init -input=false -reconfigure -backend-config=bucket=$STATE_BUCKET && terraform -chdir=infra/bootstrap apply"
  fi
else
  step "Read the plan Terraform prints, then type yes to apply it."
  confirm "Apply infra/bootstrap now?" || exit 1
  printf 'terraform {\n  backend "local" {}\n}\n' >infra/bootstrap/backend_override.tf
  in_aws "terraform -chdir=infra/bootstrap init -input=false -reconfigure && terraform -chdir=infra/bootstrap apply"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Bootstrap, step 2: move the state into its bucket"
if [[ -f infra/bootstrap/backend_override.tf || -f infra/bootstrap/terraform.tfstate ]]; then
  say "Now the bucket exists, Terraform copies bootstrap's state into it (bootstrap/terraform.tfstate)."
  rm -f infra/bootstrap/backend_override.tf
  in_aws "terraform -chdir=infra/bootstrap init -input=false -migrate-state -force-copy -backend-config=bucket=$STATE_BUCKET"
  if in_aws "aws s3api head-object --bucket $STATE_BUCKET --key bootstrap/terraform.tfstate" >/dev/null 2>&1; then
    say "${GREEN}✓${RESET} The state is in s3://$STATE_BUCKET/bootstrap/terraform.tfstate."
    confirm "Delete the local infra/bootstrap/terraform.tfstate* files?" && rm -f infra/bootstrap/terraform.tfstate*
  else
    warn "The state isn't in the bucket yet. Keep infra/bootstrap/terraform.tfstate and re-run this stage."
    exit 1
  fi
else
  say "${GREEN}✓${RESET} Nothing to move: bootstrap's state is already in $STATE_BUCKET."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub environments: staging and prod"
say "Each deploy job runs in its stack's environment, and only that environment can assume the"
say "stack's role. prod gets you as its required reviewer (the approval gate) and deploys from"
say "main only. staging deploys without approval."
GH_LOGIN=$(gh api user --jq .login)
GH_ID=$(gh api user --jq .id)
gh api -X PUT "repos/$REPO_SLUG/environments/staging" --silent
printf '{"reviewers":[{"type":"User","id":%s}],"prevent_self_review":false,"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}' "$GH_ID" |
  gh api -X PUT "repos/$REPO_SLUG/environments/prod" --input - --silent
if ! gh api "repos/$REPO_SLUG/environments/prod/deployment-branch-policies" --jq '.branch_policies[].name' | grep -qx main; then
  gh api -X POST "repos/$REPO_SLUG/environments/prod/deployment-branch-policies" -f name=main -f type=branch --silent
fi
say "${GREEN}✓${RESET} staging, and prod (reviewer $GH_LOGIN, branch main)"
open_url "https://github.com/$REPO_SLUG/settings/environments"
pause "Check both environments on that page, then press Enter"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub environment variables"
say "The deploy workflow reads these per environment. They're identifiers, not secrets."
for s in "${STACKS[@]}"; do
  set_env_var "$s" DEPLOY_ROLE_ARN "arn:aws:iam::$ACCOUNT:role/plateful-deploy-$s"
  set_env_var "$s" TF_STATE_BUCKET "$STATE_BUCKET"
  set_env_var "$s" AWS_REGION "$REGION"
done
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "First deploy of both stacks"
say "The Deploy workflow (.github/workflows/deploy.yml) makes each stack on its first run: staging,"
say "then staging's smoke checks and e2e, then prod once you approve it."
if load_outputs staging 2>/dev/null && load_outputs prod 2>/dev/null; then
  say "${GREEN}✓${RESET} Both stacks are already deployed."
elif ! gh workflow view deploy.yml -R "$REPO_SLUG" >/dev/null 2>&1; then
  warn "deploy.yml isn't on main yet: merge the PR that adds it (it then runs by itself), and re-run."
  exit 1
elif confirm "Start a Deploy run on main now?"; then
  gh workflow run deploy.yml --ref main -R "$REPO_SLUG"
  sleep 5
  RUN_ID=$(gh run list -R "$REPO_SLUG" --workflow deploy.yml --event workflow_dispatch --limit 1 --json databaseId --jq '.[0].databaseId')
  open_url "https://github.com/$REPO_SLUG/actions/runs/$RUN_ID"
  step "When the staging job passes (deploy, smoke and e2e), click Review deployments → prod → Approve and deploy."
  if gh run watch "$RUN_ID" -R "$REPO_SLUG" --exit-status; then
    say "${GREEN}✓${RESET} Both stacks are deployed."
  else
    warn "The run failed. Read its log on the page above, fix the cause and re-run this wizard."
    say "If CI can't do a stack's first apply (for example, the deploy role lacks a permission),"
    say "this wizard can deploy it once from here with your admin credentials."
    if confirm "Deploy from here instead?"; then
      ask DEPLOY_STACK "Which stack (staging or prod)?"
      "$MAKE_BIN" -s --no-print-directory build
      "$MAKE_BIN" -s --no-print-directory deploy STACK="$DEPLOY_STACK"
    fi
  fi
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "CloudFront Free plan, per distribution"
say "Each distribution goes on the flat-rate Free plan (\$0, no overage). The subscription takes the"
say "distribution and its web ACL. The account may hold three Free plan distributions."
SUBSCRIBED=$(in_aws 'aws pricing-plan-manager list-subscriptions --region us-east-1 --query "subscriptionSummaries[].resourceArns[]" --output text' || true)
for s in "${STACKS[@]}"; do
  if ! load_outputs "$s"; then warn "$s isn't deployed yet: re-run after stage 7."; continue; fi
  dist_var=DIST_ARN_$s acl_var=ACL_ARN_$s domain_var=DOMAIN_$s
  dist=${!dist_var} acl=${!acl_var}
  if [[ $SUBSCRIBED == *"$dist"* ]]; then
    say "${GREEN}✓${RESET} $s is already on a plan."
  elif confirm "Subscribe $s (${!domain_var}) to the Free plan?"; then
    if status=$(in_aws "aws pricing-plan-manager create-subscription --region us-east-1 --plan-family CloudFront --plan-tier FREE --resource-arns $dist $acl --query subscription.status --output text"); then
      say "${GREEN}✓${RESET} $s: $status. Syncing takes 2–5 minutes."
    else
      warn "AWS refused the subscription (its error is above). A ValidationException names a"
      warn "distribution feature the Free plan doesn't allow."
      SKIPPED+=("Free plan for $s")
    fi
  fi
done
open_url "https://console.aws.amazon.com/cloudfront/v4/home#/distributions"
pause "Check each distribution shows the Free plan, then press Enter"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Staging secrets"
stack_secrets staging
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Prod secrets"
stack_secrets prod
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Staging dev profile for make dev"
say "$DEV_USER (made by Terraform, staging's data only) gets an access key, saved as a profile"
say "in ~/.aws so make dev STAGING_PROFILE=<profile> can reach staging's stores."
ask STAGING_PROFILE "Profile name (Enter for $DEV_USER):"
STAGING_PROFILE=${STAGING_PROFILE:-$DEV_USER}
write_env STAGING_PROFILE "$STAGING_PROFILE"
mkdir -p ~/.aws && chmod 700 ~/.aws
if grep -qx "\[$STAGING_PROFILE\]" ~/.aws/credentials 2>/dev/null; then
  say "${GREEN}✓${RESET} ~/.aws/credentials already has [$STAGING_PROFILE]. To make a new key, delete that"
  say "section and the old key (IAM → Users → $DEV_USER), then re-run."
else
  KEYS=$(in_aws "aws iam list-access-keys --user-name $DEV_USER --query 'length(AccessKeyMetadata)' --output text")
  if [[ $KEYS -ge 2 ]]; then
    warn "$DEV_USER already has two access keys. Delete one in IAM, then re-run."
  elif confirm "Create an access key for $DEV_USER and save it as [$STAGING_PROFILE]?"; then
    read -r KEY_ID KEY_SECRET < <(in_aws "aws iam create-access-key --user-name $DEV_USER --query 'AccessKey.[AccessKeyId,SecretAccessKey]' --output text")
    (umask 077 && printf '\n[%s]\naws_access_key_id = %s\naws_secret_access_key = %s\n' \
      "$STAGING_PROFILE" "$KEY_ID" "$KEY_SECRET" >>~/.aws/credentials)
    unset KEY_SECRET
    grep -qx "\[profile $STAGING_PROFILE\]" ~/.aws/config 2>/dev/null ||
      printf '\n[profile %s]\nregion = %s\n' "$STAGING_PROFILE" "$REGION" >>~/.aws/config
    say "${GREEN}✓${RESET} saved [$STAGING_PROFILE] to ~/.aws/credentials, with region $REGION in ~/.aws/config"
  fi
fi
printf '\n'
step "In another terminal: $MAKE_BIN dev STAGING_PROFILE=$STAGING_PROFILE"
step "Open http://localhost:5173 and check the page loads, then stop it with Ctrl-C."
pause "Press Enter once make dev works against staging"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Check both URLs"
for s in "${STACKS[@]}"; do
  if ! load_outputs "$s"; then warn "$s isn't deployed yet."; SKIPPED+=("deploy $s"); continue; fi
  domain_var=DOMAIN_$s
  url=https://${!domain_var}
  say "${BOLD}$s${RESET}: $url"
  "$MAKE_BIN" -s --no-print-directory smoke URL="$url" || SKIPPED+=("fix $s's smoke checks ($url)")
  open_url "$url/week"
done
step "Open both URLs on a phone too. Staging's is for checks before a release."
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Put the admin credentials away"
unset AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY AWS_SESSION_TOKEN TF_STATE_BUCKET
if [[ $USED_ACCESS_KEY == yes ]]; then
  say "You made an admin access key for this. Delete it now: from here on, only CI deploys."
  open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
  step "Security credentials → Access keys → the key you made → Actions → Deactivate, then Delete."
  pause "Press Enter once it's deleted"
else
  say "Identity Center credentials expire by themselves. This wizard has forgotten them."
fi

finish
}

run_wizard "$@"; exit
